import type { RouseApp } from '../core/app';
import { directiveSelector } from '../core/attributes';
import { STORE_PREFIX } from '../core/constants';
import { warn } from '../core/diagnostics';
import { invokeHandler } from '../core/invoke';
import { parseStoreRef, parseTriggers } from '../core/parser';
import { getNestedVal } from '../core/path';
import { dispatchTrigger, isTriggerSource } from '../dom/events';
import type { AnyFn, BoundCleanupFn, BoundDirective, Scope } from '../types';

function bind(
  el: Element,
  scope: Scope,
  app: RouseApp,
  key: string,
  value: string,
): BoundCleanupFn | undefined {
  if (!value) {
    return bindModifiersOnly(el, app, key);
  }

  const methodName = value.trim();

  let method: unknown;
  let context: unknown;

  // Global store (e.g., `@theme.toggleMode`)
  if (methodName.startsWith(STORE_PREFIX)) {
    const ref = parseStoreRef(methodName, 'on');
    if (!ref) return;

    const { source: storeName, nestedPath } = ref;
    const storeData = app.stores.get(storeName);

    if (storeData === undefined) {
      __DEV__ && warn(`rz-on: store '@${storeName}' not found.`, el);
      return;
    }

    if (!nestedPath) {
      __DEV__ &&
        warn(`rz-on: '@${storeName}' needs a handler (e.g., @${storeName}.save).`, el);
      return;
    }

    method = getNestedVal(storeData, nestedPath);
    context = storeData;
  }

  // Local scope method
  else {
    method = scope[methodName];
    context = scope;
  }

  // Validate that the resolved target is actually a function
  if (typeof method !== 'function') {
    __DEV__ && warn(`rz-on: handler '${methodName}' is undefined or not a function.`, el);
    return;
  }

  const cleanups = parseTriggers(key).map((trigger) =>
    dispatchTrigger(trigger, {
      el,
      app,
      action: (e?: Event) =>
        invokeHandler(
          method as AnyFn,
          context,
          methodName,
          scope,
          el,
          e ?? new CustomEvent(trigger.event),
        ),
    }),
  );

  return (() => cleanups.forEach((fn) => fn())) as BoundCleanupFn;
}

/**
 * Binds handler-less triggers, which only apply `prevent`, `stop`, or `stop-immediate`.
 * Navigation isn't suppressed: with no handler, nothing takes over the link's job.
 */
function bindModifiersOnly(el: Element, app: RouseApp, key: string): BoundCleanupFn {
  const cleanups = parseTriggers(key).flatMap((trigger) => {
    const { prevent, stop, stopImmediate } = trigger.options;
    if (isTriggerSource(trigger.event) || !(prevent || stop || stopImmediate)) {
      __DEV__ &&
        warn(
          `rz-on: '${trigger.event}' has no handler and no prevent, stop, or stop-immediate, so it does nothing. Ignoring.`,
          el,
        );
      return [];
    }
    return dispatchTrigger(trigger, {
      el,
      app,
      action: () => {},
      suppressNavigation: false,
    });
  });

  return (() => cleanups.forEach((fn) => fn())) as BoundCleanupFn;
}

export const rzOn = {
  slug: 'on',
  selector: directiveSelector('on'),
  bind,
} as const satisfies BoundDirective;
